(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.018+t*0.25)*20 + Math.cos(y*0.013-t*0.18)*15 + Math.sin((x+y)*0.008+t*0.4)*8;
  const wy = Math.cos(y*0.018-t*0.22)*20 + Math.sin(x*0.016+t*0.3)*15 + Math.cos((x-y)*0.009-t*0.35)*8;
  const sx = x+wx, sy = y+wy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.08, 2.0, 1.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.1, 1.7, 0.9],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.06, 2.3, 1.1],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.12, 1.5, 0.8],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.07, 2.6, 1.05],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.09, 1.9, 0.95],
    [80+Math.sin(t*0.45+3)*70, 40+Math.cos(t*0.65+2)*50, 0.11, 2.1, 0.85],
    [400+Math.cos(t*0.55+1)*60, 200+Math.sin(t*0.75+4)*55, 0.075, 2.4, 1.15],
    [200+Math.sin(t*0.7+2)*90, 220+Math.cos(t*0.3+5)*40, 0.095, 1.6, 0.9],
    [300+Math.cos(t*0.42+3)*110, 30+Math.sin(t*0.58+1)*65, 0.065, 2.8, 1.0]
  ];
  let aS=0, iS=0, cS=0, wS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f-t*sp)*w;
    const wave2 = Math.sin(d*f*1.618-t*sp*0.78+0.5)*w*0.4;
    aS += wave + wave2*0.3;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS += Math.cos(d*f*0.5-t*sp*0.4+2.0)*w*0.6;
    wS += Math.sin(d*f*0.3+t*sp*0.9-1.0)*w*0.5;
  }
  const n=10, act=aS/n, inh=iS/n, cou=cS/n, wav=wS/n;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2
    + Math.sin((sx+sy)*0.12+t*2.5)*0.2 + Math.sin((sx-sy)*0.1-t*2)*0.2
    + Math.sin(sx*0.07*Math.cos(t*0.2)+sy*0.05*Math.sin(t*0.15)+t*0.6)*0.15;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const spiral = (Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4
    + Math.sin(dist*0.03-ang*5+t*0.8)*0.25 + Math.cos(dist*0.06+ang*2-t*1.8)*0.15;
  const voronoi = (() => {
    let md = 1e9, md2 = 1e9;
    for (const [sX,sY] of src) {
      const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
      if (d < md) { md2 = md; md = d; } else if (d < md2) { md2 = d; }
    }
    return Math.sin((md2-md)*0.3)*0.5;
  })();
  const r1 = Math.tanh((act - inh*0.7 + bg*0.3 + spiral)*2.2);
  const r2 = Math.tanh((cou*0.5 + wav*0.4 - act*inh*0.3 + voronoi*0.5)*1.8);
  const diff = Math.tanh((r1 - r2*0.6 + spiral*0.2 + bg*0.15)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const micro = Math.tanh((Math.sin(sx*0.3+t*1.5)*Math.cos(sy*0.25-t*1.2)+Math.sin((sx-sy)*0.2+t*0.8)*0.4)*1.2)*0.15;
  const blend = diff*0.55 + r1*0.2 + r2*0.15 + cell*0.05 + micro*0.05;
  const v = blend*0.5+0.5;
  const pal = [
    [5,10,45],[10,35,85],[12,70,110],[18,115,120],[45,155,105],
    [120,180,75],[190,185,55],[220,155,60],[215,110,65],[185,65,65],
    [140,35,70],[85,18,65],[40,12,55],[5,10,45]
  ];
  const idx = v*(pal.length-1), i = Math.min(idx|0, pal.length-2), f = idx-i;
  const sm = f*f*(3-2*f);
  const lum = 0.75 + Math.sin(diff*Math.PI)*0.25;
  const edge = Math.abs(diff)>0.65 ? 1.2 : Math.abs(diff)>0.4 ? 1.08 : 1.0;
  const glow = Math.max(0, 1-Math.abs(diff)*2)*0.15;
  return [
    Math.min(255, ((pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge + glow*40)|0),
    Math.min(255, ((pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*edge + glow*25)|0),
    Math.min(255, ((pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*edge + glow*15)|0)
  ];
}
